// helper: aplica um filtro de busca (_s) e mede end-item/total como o count widget faria
function measure($qid, $label, $args_override) {
  $m = \Jet_Engine\Query_Builder\Manager::instance();
  // pega uma instancia FRESCA da query
  $q = $m->get_query_by_id($qid);
