  $q->get_items(); // executa
  $total   = $q->get_items_total_count();
  $visible = $q->get_items_page_count();      // = %visible% (post_count) 
  $enditem = $q->get_end_item_index_on_page(); // = [end-item]
  printf("%-28s total=%-4s visible(post_count)=%-4s end-item=%-4s\n", $label, $total, $visible, $enditem);
}

