    countLineText: countLine ? countLine.textContent.trim() : '(não encontrado)',
    countSpans: Array.from(document.querySelectorAll('.jet-engine-query-count')).map(s => ({cls: s.className, val: s.textContent, q: s.dataset.query})),
    cardsRendered: cards,
    matchedHeadings: headings
  };
}

