() => {
  // find a checkbox/select filter on espiral and apply it
  const cb = document.querySelector('.jet-checkboxes-list__input, .jet-smart-filters-checkboxes input[type=checkbox]');
  const sel = document.querySelector('.jet-smart-filters-select select, select.jet-filter-select');
  let applied = null;
  if (cb) { cb.checked = true; cb.dispatchEvent(new Event('change',{bubbles:true})); applied = 'checkbox:'+cb.value; }
  else if (sel) { sel.selectedIndex = 1; sel.dispatchEvent(new Event('change',{bubbles:true})); applied = 'select:'+sel.value; }
  return {applied, hasCb: !!cb, hasSel: !!sel};
}

