docker exec -u www-data concertacao-dev-wordpress wp eval '
foreach ([26827, 75718] as $pid) {
  $raw = get_post_meta($pid, "_elementor_data", true);
  $data = json_decode($raw, true);
  if (!is_array($data)) { echo "ERRO decode em $pid\n"; continue; }
  $changed = false;
  $mut = function(&$els) use (&$mut, &$changed) {
    foreach ($els as &$el) {
      if (($el["id"] ?? "") === "23d592f") {
        $el["settings"]["custom_query"] = "yes";   // CHAVE CORRETA (gate do get_query_id)
        $el["settings"]["custom_query_id"] = "76";
        // remove a chave errada que eu tinha setado, p/ nao confundir
        unset($el["settings"]["use_custom_query"]);
        $el["settings"]["posts_num"] = 12;
        $changed = true;
      }
      if (!empty($el["elements"])) $mut($el["elements"]);
    }
  };
  $mut($data);
  if (!$changed) { echo "AVISO 23d592f nao achado em $pid\n"; continue; }
  $encoded = wp_json_encode($data);
  if (json_decode($encoded) === null) { echo "ERRO encode $pid\n"; continue; }
  update_post_meta($pid, "_elementor_data", wp_slash($encoded));
  echo "OK $pid: custom_query=yes custom_query_id=76 (use_custom_query removido)\n";
}
